vectors_test() ->
    lists:foreach(
        fun({Len, Ref64, Ref128}) ->
            Data = seq_bytes(Len),
            ?assertEqual(Ref64, hexl(i2p_siphash:hash_le(Data, ?KEY))),
            ?assertEqual(Ref128, hexl(i2p_siphash:hash_128_le(Data, ?KEY)))
        end,
        vectors()
    ),
    ok.

key_sensitivity_test() ->
    %% Flipping a single key bit must change both outputs.
    Data = <<16#00, 16#01, 16#02, 16#03, 16#04, 16#05, 16#06, 16#07>>,
    K1 = ?KEY,
    <<H:8, Rest/binary>> = K1,
    K2 = <<(H bxor 1):8, Rest/binary>>,
    ?assertNotEqual(i2p_siphash:hash(Data, K1), i2p_siphash:hash(Data, K2)),
    ?assertNotEqual(i2p_siphash:hash_128(Data, K1), i2p_siphash:hash_128(Data, K2)).

bad_key_test() ->
    ?assertError(function_clause, i2p_siphash:hash(<<1, 2, 3>>, <<1, 2, 3>>)).
